<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { api, uploadMedia } from '../api';
import { type Row, formatTime } from '../../shared/domain';
import { useShop, productCategories, orderStates, orderSettlementLabel, money } from '../../shared/useShop';
const props = defineProps<{ user: Row | null }>();const emit = defineEmits<{ (event: 'join'): void }>();
const { products, orders, selected, filter, query, tab, manage, error, message, loading, busy, ordering, orderForm, admin, filtered, load, resetFilters, buy, submitOrder, saveProduct, act } = useShop(() => props.user, api);
const editing = ref(false), product = ref<Row>({}), uploading = ref(false), actionRow = ref<Row | null>(null), actionName = ref(''), note = ref('');
const actionDialog = ref<HTMLDialogElement | null>(null);
let returnFocus: HTMLElement | null = null;
function trapActionFocus(event: KeyboardEvent) {
  const controls = Array.from(actionDialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled), textarea:not(:disabled), input:not(:disabled), select:not(:disabled)') || []);
  const first = controls[0], last = controls[controls.length - 1];
  if (!first) { event.preventDefault();return; }
  if (event.shiftKey && document.activeElement === first) { event.preventDefault();last.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault();first.focus(); }
}
watch(actionRow, async row => {
  if (row) { returnFocus = document.activeElement as HTMLElement;await nextTick();actionDialog.value?.showModal(); }
  else { await nextTick();returnFocus?.focus(); }
});
watch(() => props.user?.id, () => { actionRow.value = null;editing.value = false; });
const total = computed(() => (selected.value?.priceCents || 0) * Number(orderForm.value.quantity || 0) + (orderForm.value.delivery === 'shipping' ? selected.value?.shippingCents || 0 : 0));
function edit(row?: Row) { product.value = row ? { ...row, images: [...row.images], price: (row.priceCents / 100).toFixed(2), shippingFee: (row.shippingCents / 100).toFixed(2) } : { title: '', category: productCategories[0], description: '', specification: '', origin: '江苏沭阳', seller: '', sellerContact: '', afterSales: '', price: '', shippingFee: '0', stock: 0, images: [], status: 'draft' };editing.value = true;selected.value = null; }
async function save() { if (await saveProduct(product.value)) editing.value = false; }
async function upload(event: Event) { const target = product.value, userId = props.user?.id;const input = event.target as HTMLInputElement;uploading.value = true;try { for (const file of Array.from(input.files || [])) { if (!editing.value || product.value !== target || props.user?.id !== userId || target.images.length >= 8) break;const row = await uploadMedia(file, 'product');if (!editing.value || product.value !== target || props.user?.id !== userId) break;target.images.push(row.id); } } catch(e) { error.value = (e as Error).message; } finally { uploading.value = false;input.value = ''; } }
function order(row: Row) { if (props.user?.status !== 'approved') emit('join');else buy(row); }
function action(row: Row, name: string) { actionRow.value = row;actionName.value = name;note.value = ''; }
async function confirmAction() { if (actionRow.value && await act(actionRow.value, actionName.value, note.value)) actionRow.value = null; }
const actionLabels: Record<string,string> = { confirm: '确认订单', cancel: '取消订单', settle: '核实线下结算', refund: '核实退款并取消', ship: '登记发货', ready: '通知可自提', receive: '确认已收货' };
</script>
<style scoped>
.shop form{min-width:0;width:100%}
.shop form>label,.shop .form-grid>label{display:flex;flex-direction:column;gap:8px;margin:16px 0;font-size:14px;min-width:0;color:#3d5663}
.shop input:not([type=checkbox]),.shop select,.shop textarea{box-sizing:border-box;display:block;width:100%;max-width:100%;min-width:0;padding:12px 14px;border:1px solid #dcd7c6;border-radius:10px;background:#fcfaf5;color:#304b5a;font:inherit;font-size:16px}
.shop textarea{min-height:110px;resize:vertical}
.shop .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}
.shop form>label.checkbox{flex-direction:row;align-items:flex-start;line-height:1.8}
.shop .checkbox input{flex:none;margin-top:6px}
@media(max-width:600px){.shop .form-grid{grid-template-columns:minmax(0,1fr)}.shop .order-form,.shop .product-editor{padding:20px}.shop form>label{overflow-wrap:anywhere}}
</style>
<template><section class="shop" :aria-busy="loading"><div class="shop-heading"><div><p class="eyebrow">A TASTE OF HOME</p><h2>家乡好物，捎一份乡情。</h2><p>熟悉的家乡味道，也是一份送给亲友的心意。</p></div><div v-if="admin" class="button-row"><button class="outline" @click="manage = !manage; editing = false">{{ manage ? '返回会员视图' : '商品与订单管理' }}</button><button class="primary" @click="edit()">新增商品</button></div></div><p class="shop-note">在线下单，卖家人工确认。商品价款在线下结算，本平台不在线扣款。</p><p v-if="message" role="status" class="status-note">{{ message }}</p><div v-if="error" role="alert" class="form-error">{{ error }} <button v-if="!ordering && !editing && !actionRow" class="text-button" :disabled="loading || busy" @click="load">重新加载</button></div><p v-if="loading" role="status" class="form-tip">正在加载商品与订单…</p>
<form v-if="editing" class="panel product-editor" @submit.prevent="save"><h3>{{ product.id ? '编辑商品' : '新增家乡特产' }}</h3><div class="form-grid"><label>商品名称<input v-model="product.title" required minlength="2" maxlength="80"></label><label>分类<select v-model="product.category"><option v-for="item in productCategories" :key="item">{{ item }}</option></select></label><label>规格<input v-model="product.specification" required minlength="2" maxlength="150" placeholder="例如500克／袋"></label><label>产地<input v-model="product.origin" required minlength="2" maxlength="100"></label><label>单价（元）<input v-model="product.price" required type="number" min="0.01" max="100000" step="0.01"></label><label>每单运费（元）<input v-model="product.shippingFee" required type="number" min="0" max="100000" step="0.01"></label><label>可售库存<input v-model="product.stock" required type="number" min="0" max="1000000"></label><label>状态<select v-model="product.status"><option value="draft">草稿</option><option value="published">上架展示</option><option value="withdrawn">已下架</option></select></label><label>供货商<input v-model="product.seller" required minlength="2" maxlength="100"></label><label>售后联系电话<input v-model="product.sellerContact" required minlength="5" maxlength="80"></label></div><label>商品介绍<textarea v-model="product.description" required minlength="10" maxlength="5000"></textarea></label><label>售后说明<textarea v-model="product.afterSales" required minlength="10" maxlength="1000"></textarea></label><label>真实商品图片（JPG/PNG，最多8张）<input type="file" accept="image/png,image/jpeg" multiple :disabled="uploading" @change="upload"></label><div class="image-id-list"><span v-for="(id,index) in product.images" :key="id">图片 {{ index + 1 }} <button type="button" @click="product.images.splice(index,1)">移除 ×</button></span></div><div class="button-row"><button class="primary" :disabled="busy || uploading">{{ uploading ? '图片上传中…' : '保存商品' }}</button><button type="button" class="outline" @click="editing = false">返回</button></div></form>
<form v-else-if="ordering && selected" class="panel order-form" @submit.prevent="submitOrder"><button type="button" class="text-button" :disabled="busy" @click="ordering = false">← 商品详情</button><h3>填写订单</h3><p>{{ selected.title }} · {{ selected.specification }}</p><label>购买数量<input v-model="orderForm.quantity" type="number" required min="1" :max="Math.min(99, selected.stock)"></label><label>配送方式<select v-model="orderForm.delivery"><option value="shipping">快递配送</option><option value="pickup">到店／活动现场自提</option></select></label><div class="form-grid"><label>联系人<input v-model="orderForm.name" required minlength="2" maxlength="30"></label><label>联系电话<input inputmode="tel" autocomplete="tel" v-model="orderForm.phone" required pattern="1[3-9][0-9]{9}" maxlength="11"></label></div><label v-if="orderForm.delivery === 'shipping'">收货地址<textarea v-model="orderForm.address" required minlength="5" maxlength="300"></textarea></label><p v-else class="form-tip">自提时间与地点由卖家确认后告知，请留意订单履约信息。</p><div class="order-total">预计合计 <strong>{{ money(total) }}</strong><span>含运费 {{ money(orderForm.delivery === 'shipping' ? selected.shippingCents : 0) }}</span></div><label class="checkbox"><input v-model="orderForm.consent" type="checkbox" required>我确认商品与售后说明，知悉人工确认、线下结算；收货信息仅用于订单履约。</label><button class="primary full" :disabled="busy">{{ busy ? '正在提交订单…' : '提交订单 · 待人工确认' }}</button></form>
<template v-else-if="selected"><button class="text-button" @click="selected = null">← 全部家乡特产</button><div class="product-detail"><div class="product-images"><img v-for="id in selected.images" :key="id" :src="'/api/media/' + id" :alt="selected.title"></div><div class="panel"><span class="tag">{{ selected.category }}</span><h2>{{ selected.title }}</h2><p>{{ selected.specification }} · {{ selected.origin }}</p><strong class="price">{{ money(selected.priceCents) }}</strong><p class="product-meta">可售 {{ selected.stock }} 件 · 运费 {{ money(selected.shippingCents) }}／单 · 支持自提</p><button class="primary full" :disabled="selected.stock < 1 || selected.status !== 'published'" @click="order(selected)">{{ selected.stock > 0 ? '填写订单' : '暂时售罄' }}</button><div class="prose product-copy">{{ selected.description }}</div><h3>供货与售后</h3><p>{{ selected.seller }} · {{ selected.sellerContact }}</p><p class="prose">{{ selected.afterSales }}</p></div></div></template>
<template v-else><div class="chips"><button :class="{ selected: tab === 'products' }" @click="tab = 'products'">家乡特产</button><button :class="{ selected: tab === 'orders' }" @click="user?.status === 'approved' ? tab = 'orders' : emit('join')">{{ manage ? '订单处理' : '我的订单' }}</button></div><template v-if="tab === 'products'"><div class="filterbar"><input v-model="query" aria-label="搜索家乡特产" placeholder="搜索家乡味道、产地"><div class="chips"><button v-for="item in ['全部', ...productCategories]" :key="item" :class="{ selected: filter === item }" @click="filter = item">{{ item }}</button></div></div><div v-if="!loading && !error && !filtered.length" class="empty"><template v-if="query.trim() || filter !== '全部'">没有找到符合条件的商品。<button class="outline" @click="resetFilters">清除筛选</button></template><template v-else>家乡好物正在准备中，欢迎常来看看。</template></div><div class="product-grid"><article v-for="row in filtered" :key="row.id" class="product-card"><button @click="selected = row"><img v-if="row.images.length && row.status === 'published'" :src="'/api/media/' + row.images[0]" :alt="row.title" loading="lazy"><div v-else class="product-placeholder">乡土 · 好物</div><div><small>{{ row.origin }} · {{ row.category }}</small><h3>{{ row.title }}</h3><p>{{ row.specification }}</p><strong class="price">{{ money(row.priceCents) }}</strong><span class="stock">库存 {{ row.stock }}</span></div></button><button v-if="manage" class="text-button edit-product" @click="edit(row)">{{ row.status === 'published' ? '编辑／下架' : '编辑／上架' }}</button></article></div></template><template v-else><div v-if="!loading && !error && !orders.length" class="empty">还没有订单。<button class="outline" @click="tab = 'products'">去逛家乡特产</button></div><article v-for="row in orders" :key="row.id" class="panel shop-order"><div class="order-heading"><span>{{ row.orderNo }} · {{ formatTime(row.createdAt) }}</span><span class="tag">{{ orderStates[row.status] }}</span></div><h3>{{ row.title }} <small>× {{ row.quantity }}</small></h3><p>{{ row.specification }} · {{ money(row.totalCents) }}（含运费）</p><p class="settlement-label">{{ orderSettlementLabel(row) }}</p><p>{{ row.name }} · {{ row.phone }} · {{ row.delivery === 'shipping' ? row.address : '自提' }}</p><p v-if="row.fulfillment" class="status-note">履约信息：{{ row.fulfillment }}</p><p v-if="row.settlementNote" class="form-tip">结算记录：{{ row.settlementNote }}</p><p class="form-tip">卖家：{{ row.seller }} · {{ row.sellerContact }}</p><div class="button-row"><template v-if="manage"><button v-if="row.status === 'pending'" class="primary small" @click="action(row,'confirm')">确认订单</button><button v-if="['confirmed','shipped','ready','completed'].includes(row.status) && row.settlement === 'unconfirmed'" class="outline small" @click="action(row,'settle')">核实线下结算</button><button v-if="row.status === 'confirmed'" class="outline small" @click="action(row,row.delivery === 'shipping' ? 'ship' : 'ready')">{{ row.delivery === 'shipping' ? '登记发货' : '通知自提' }}</button><button v-if="['pending','confirmed'].includes(row.status) && row.settlement === 'confirmed'" class="text-button" @click="action(row,'refund')">核实退款并取消</button></template><button v-if="['pending','confirmed'].includes(row.status) && row.settlement !== 'confirmed'" class="text-button" @click="action(row,'cancel')">取消订单</button><button v-if="row.buyerId === user?.id && ['shipped','ready'].includes(row.status)" class="primary small" @click="action(row,'receive')">确认已收货</button></div></article></template></template>
<dialog v-if="actionRow" ref="actionDialog" class="order-action-dialog" aria-labelledby="order-action-title" @keydown.tab="trapActionFocus" @cancel.prevent="!busy && (actionRow = null)"><section class="panel"><h3 id="order-action-title">{{ actionLabels[actionName] }}</h3><p>{{ actionRow.title }} · {{ money(actionRow.totalCents) }}</p><p v-if="actionName === 'settle' || actionName === 'refund'" class="form-tip">请核实真实线下记录后再登记，此操作不会发起线上收款或退款。</p><p v-if="actionName === 'receive'" class="form-tip">请确认已实际收到商品。</p><label v-if="['settle','refund','ship','ready'].includes(actionName)">{{ actionName === 'ship' ? '物流公司与运单号' : actionName === 'ready' ? '自提地点与时间' : '核实记录（至少5字）' }}<textarea v-model="note" maxlength="300"></textarea></label><p v-if="error" class="form-error">{{ error }}</p><div class="button-row"><button class="primary" :disabled="busy" @click="confirmAction">确认</button><button class="outline" :disabled="busy" @click="actionRow = null">返回</button></div></section></dialog></section></template>
<style scoped>.shop-heading{display:flex;justify-content:space-between;align-items:center;gap:25px;margin:16px 0 28px}.shop-heading h2{font-size:28px;margin:12px 0}.shop-heading p{color:#7e8987;font-size:13px}.shop-note{background:#ede7d7;border-radius:12px;padding:15px 20px;font-size:12px;line-height:1.8;color:#87714c;margin-bottom:25px}.product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.product-card{background:#fffefa;border:1px solid #e6dfd1;border-radius:20px;overflow:hidden}.product-card>button:first-child{width:100%;text-align:left}.product-card img,.product-placeholder{width:100%;height:230px;object-fit:cover}.product-placeholder{display:grid;place-items:center;background:#e6e5d2;color:#9e8a5f;font-size:24px}.product-card>button>div:last-child{padding:22px}.product-card small,.product-card p{color:#8d9385;font-size:12px}.product-card h3{margin:10px 0;font-size:19px}.price{font:27px Georgia,serif;color:#a7793f;display:inline-block;margin-top:14px}.stock{font-size:11px;float:right;margin-top:24px;color:#959780}.edit-product{padding:0 22px 20px}.product-detail{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:25px}.product-images{display:flex;flex-direction:column;gap:15px}.product-images img{width:100%;border-radius:22px}.product-detail h2{font-size:28px;margin:20px 0}.product-detail p{font-size:13px;line-height:1.9;color:#7b8584}.product-meta{margin-bottom:25px}.product-copy{margin:30px 0;white-space:pre-wrap}.order-form,.product-editor{max-width:780px}.order-form h3{font-size:24px;margin:18px 0}.order-total{display:flex;align-items:center;gap:20px;padding:22px 0;border-top:1px solid #e9e1cf}.order-total strong{color:#a7793f;font-size:26px}.order-total span{font-size:12px;color:#91856c}.order-heading{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#8c917f}.shop-order h3{font-size:19px;margin-top:18px}.shop-order p{font-size:13px;line-height:1.9}.settlement-label{color:#a68449}.image-id-list{display:flex;flex-wrap:wrap;gap:15px;font-size:13px;margin:15px 0}.image-id-list span{background:#eee7d6;padding:10px;border-radius:8px}.order-action-dialog{border:0;padding:0;border-radius:20px;width:min(550px,calc(100vw - 40px));max-height:85vh}.order-action-dialog::backdrop{background:#1e374b88}.order-action-dialog>.panel{margin:0;width:100%}.order-action-dialog h3{font-size:22px;margin-bottom:20px}@media(max-width:1000px){.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.shop-heading{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.product-detail{grid-template-columns:1fr}.product-card img,.product-placeholder{height:150px}.product-grid{gap:12px}.product-card>button>div:last-child{padding:14px}.product-card h3{font-size:16px}.stock{float:none;display:block;margin-top:8px}.price{font-size:23px}.shop-heading h2{font-size:23px}.order-total{flex-wrap:wrap}}</style>
